#[inline(always)]
pub fn try_min_with<const O: u32>(a: f32, b: f32) -> Result<f32, PrimitiveError> {
    try_min_f32x4_lane_with::<O, _>(ScalarToken, a, b)
}
/// Configured array max, selecting once; widths 1, 4, 8, and enabled 16.
#[inline(always)]
pub fn try_max_array_with<const O: u32, const N: usize>(
    a: [f32; N],
    b: [f32; N],
) -> Result<[f32; N], PrimitiveError> {
    const {
        assert!(MinMaxOptions::valid(O), "invalid primitive options");
    }
    let mut out = [0.0; N];
    if N == 1 {
        let result = auto_f32x4::<O, true>((
            core::array::from_fn(|i| a[if N == 1 { 0 } else { i }]),
            core::array::from_fn(|i| b[if N == 1 { 0 } else { i }]),
        ))
        .map_err(|e| PrimitiveError {
            lane_mask: if N == 1 { e.lane_mask & 1 } else { e.lane_mask },
            ..e
        })?;
        out.copy_from_slice(&result[..N]);
        return Ok(out);
    }
    if N == 4 {
        let result = auto_f32x4::<O, true>((
            core::array::from_fn(|i| a[if N == 1 { 0 } else { i }]),
            core::array::from_fn(|i| b[if N == 1 { 0 } else { i }]),
        ))
        .map_err(|e| PrimitiveError {
            lane_mask: if N == 1 { e.lane_mask & 1 } else { e.lane_mask },
            ..e
        })?;
        out.copy_from_slice(&result[..N]);
        return Ok(out);
    }
    if N == 8 {
        let result = auto_f32x8::<O, true>((
            core::array::from_fn(|i| a[if N == 1 { 0 } else { i }]),
            core::array::from_fn(|i| b[if N == 1 { 0 } else { i }]),
        ))
        .map_err(|e| PrimitiveError {
            lane_mask: if N == 1 { e.lane_mask & 1 } else { e.lane_mask },
            ..e
        })?;
        out.copy_from_slice(&result[..N]);
        return Ok(out);
    }
    #[cfg(feature = "w512")]
    if N == 16 {
        let result = auto_f32x16::<O, true>((
            core::array::from_fn(|i| a[if N == 1 { 0 } else { i }]),
            core::array::from_fn(|i| b[if N == 1 { 0 } else { i }]),
        ))
        .map_err(|e| PrimitiveError {
            lane_mask: if N == 1 { e.lane_mask & 1 } else { e.lane_mask },
            ..e
        })?;
        out.copy_from_slice(&result[..N]);
        return Ok(out);
    }
    Err(PrimitiveError {
        kind: PrimitiveErrorKind::UnsupportedWidth,
        lane_mask: 0,
    })
}
/// Configured scalar max. Scalar min/max needs no CPU detection.
#[inline(always)]
pub fn try_max_with<const O: u32>(a: f32, b: f32) -> Result<f32, PrimitiveError> {
    try_max_f32x4_lane_with::<O, _>(ScalarToken, a, b)
}
